function robotSim(commands, obstacles) {
  const dx = [0, 1, 0, -1];
  const dy = [1, 0, -1, 0];
  const blocked = new Set();
  for (const [ox, oy] of obstacles) {
    blocked.add(`${ox},${oy}`);
  }
  let x = 0;
  let y = 0;
  let dir = 0;
  let best = 0;
  for (const command of commands) {
    if (command === -2) {
      dir = (dir + 3) % 4;
    } else if (command === -1) {
      dir = (dir + 1) % 4;
    } else {
      for (let step = 0; step < command; step++) {
        const nextX = x + dx[dir];
        const nextY = y + dy[dir];
        if (blocked.has(`${nextX},${nextY}`)) {
          break;
        }
        x = nextX;
        y = nextY;
        best = Math.max(best, x * x + y * y);
      }
    }
  }
  return best;
}

