function robotSim(commands, obstacles) {
  // Keep a direction vector, rotate it by hand, and scan the obstacle list on every step.
  let px = 0, py = 0, vx = 0, vy = 1;
  const visited = [[0, 0]];
  for (const c of commands) {
    if (c === -1) [vx, vy] = [vy, -vx];
    else if (c === -2) [vx, vy] = [-vy, vx];
    else {
      for (let k = 0; k < c; k++) {
        if (obstacles.some(([ox, oy]) => ox === px + vx && oy === py + vy)) break;
        px += vx; py += vy;
        visited.push([px, py]);
      }
    }
  }
  return Math.max(...visited.map(([a, b]) => a * a + b * b));
}

