function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 12);
  const turnRate = large ? 0.1 + rand() * 0.4 : 0.35;
  const commands = Array.from({ length: n }, () => (rand() < turnRate ? (rand() < 0.5 ? -2 : -1) : 1 + Math.floor(rand() * 9)));
  const count = large ? 2000 : Math.floor(rand() * 9);
  const near = large ? 150 : 6;
  const obstacles = [];
  for (let i = 0; i < count; i++) {
    if (large && rand() < 0.3) obstacles.push([Math.floor(rand() * 60001) - 30000, Math.floor(rand() * 60001) - 30000]);
    else obstacles.push([Math.floor(rand() * (2 * near + 1)) - near, Math.floor(rand() * (2 * near + 1)) - near]);
  }
  if (rand() < 0.3) obstacles.push([0, 0]);
  return [commands, obstacles];
}
